async function main(){
  const out = [];
  const ids = ['1:22','1:25','1:30','1:40','2:4','3:45','3:5','2:33'];
  function fillsStr(f){ try{ return JSON.stringify(f).replace(/\s+/g,'').slice(0,140);}catch(e){return '?';} }
  function ser(n,d){
    const i = '  '.repeat(d);
    let s = i + n.type + ' id=' + n.id + ' "' + n.name + '" ' + Math.round(n.width) + 'x' + Math.round(n.height);
    if('x' in n) s += ' @' + Math.round(n.x*10)/10 + ',' + Math.round(n.y*10)/10;
    if('layoutMode' in n && n.layoutMode !== 'NONE'){
      s += ' AL[' + n.layoutMode + ' pad=' + n.paddingLeft + ',' + n.paddingTop + ',' + n.paddingRight + ',' + n.paddingBottom + ' gap=' + n.itemSpacing + ' pSz=' + n.primaryAxisSizingMode + ' cSz=' + n.counterAxisSizingMode + ' cAl=' + n.counterAxisAlignItems + ']';
    }
    if('fills' in n && Array.isArray(n.fills) && n.fills.length) s += ' fills=' + fillsStr(n.fills);
    if('strokes' in n && n.strokes && n.strokes.length) s += ' strokes=' + fillsStr(n.strokes) + ' sw=' + n.strokeWeight;
    if('cornerRadius' in n && n.cornerRadius && n.cornerRadius !== 0) s += ' r=' + n.cornerRadius;
    if('effects' in n && n.effects && n.effects.length) s += ' fx=' + JSON.stringify(n.effects).replace(/\s+/g,'').slice(0,120);
    if(n.type === 'TEXT'){
      s += ' text="' + n.characters.replace(/\n/g,'\\n').slice(0,50) + '"';
      try{ s += ' font=' + JSON.stringify(n.fontName) + ' fs=' + n.fontSize; }catch(e){ s += ' mixedFont'; }
      s += ' fills=' + fillsStr(n.fills);
    }
    if(n.type === 'INSTANCE') s += ' main=' + n.mainComponent.name + '(' + n.mainComponent.id + ')';
    out.push(s);
    if(d < 4 && 'children' in n){ for(const c of n.children) ser(c, d+1); }
  }
  for(const id of ids){ const n = await figma.getNodeByIdAsync(id); if(n){ ser(n,0); out.push('---'); } else out.push('MISSING ' + id); }
  const fonts = await figma.listAvailableFontsAsync();
  const rob = fonts.filter(f => f.fontName.family === 'Roboto').map(f => f.fontName.style);
  out.push('Roboto styles: ' + rob.join(', '));
  return out.join('\n');
}
