const out=[];
const names=['01_Aktivitas','02_Trending','03_Detail_Saham','04_Top_Up_Metode','05_Top_Up_Nominal','06_Top_Up_Pembayaran'];
const frames=figma.currentPage.children.filter(n=>names.includes(n.name));
for(const f of frames){
  out.push('== '+f.name+' '+f.id);
  for(const c of f.children){ out.push(`  ${c.name} ${c.id} x=${Math.round(c.x)} y=${Math.round(c.y)} w=${Math.round(c.width)} h=${Math.round(c.height)}`); }
}
const compIds=['10:35','10:54','10:60','10:43','10:11','11:17','11:2','11:28','11:31','11:49','11:54','11:18'];
for(const id of compIds){
  const n=figma.getNodeById(id);
  if(!n){out.push('COMP '+id+' MISSING');continue;}
  out.push(`COMP ${n.name} ${id} ${Math.round(n.width)}x${Math.round(n.height)} clip=${n.clipsContent} mode=${n.layoutMode}`);
  if(n.layoutMode!=='NONE'){
    for(const c of n.children){ out.push(`   . ${c.name} y=${Math.round(c.y)} h=${Math.round(c.height)} w=${Math.round(c.width)} grow=${c.layoutGrow} fillH=${c.layoutSizingHorizontal}`);}
  }
}
return out.join('\n');

const out=[];
const scrIds=['16:2','17:2','18:2','20:2','20:117','21:2'];
const interesting=/head|watch|trending|dana|grid|keystat|chart|stock|trend|rec |index|method|action|compare|amount|stepper|dest|countdown|payment|guide|logo|range/i;
for(const sid of scrIds){
  const f=figma.getNodeById(sid);
  if(!f){out.push('SCREEN '+sid+' MISSING');continue;}
  out.push('== '+f.name+' '+sid);
  for(const c of f.children){
    out.push(`  ${c.name} ${c.id} x=${Math.round(c.x)} y=${Math.round(c.y)} w=${Math.round(c.width)} h=${Math.round(c.height)}`);
    if(interesting.test(c.name)){
      for(const d of c.children){ out.push(`     . ${d.name} ${d.id} x=${Math.round(d.x)} y=${Math.round(d.y)} w=${Math.round(d.width)} h=${Math.round(d.height)}`);}
    }
  }
}
const compIds=['8:36','8:43','8:51','8:70','10:43','11:60'];
for(const id of compIds){
  const n=figma.getNodeById(id);
  if(!n){out.push('C '+id+' MISSING');continue;}
  out.push(`C ${n.name} ${id} ${Math.round(n.width)}x${Math.round(n.height)} mode=${n.layoutMode} pPrim=${n.primaryAxisSizingMode} pCount=${n.counterAxisSizingMode} gap=${n.itemSpacing} pad=${n.paddingTop},${n.paddingRight},${n.paddingBottom},${n.paddingLeft}`);
  for(const c of n.children){ out.push(`   . ${c.name} grow=${c.layoutGrow} h=${Math.round(c.height)} w=${Math.round(c.width)} sizing=${c.layoutSizingHorizontal}/${c.layoutSizingVertical}`);
    if(c.children){for(const d of c.children){out.push(`      .. ${d.name} ${Math.round(d.width)}x${Math.round(d.height)} ${d.layoutSizingHorizontal}/${d.layoutSizingVertical} x=${Math.round(d.x)} y=${Math.round(d.y)}`);}}}
}
return out.join('\n');

const out=[];
