const screens=figma.root.findAll(n=>n.type==='FRAME'&&/^0[1-6]_/.test(n.name));
const out=[];
for(const s of screens){
  let p=s.parent; let chain=[];
  while(p&&p.type!=='PAGE'){chain.push(p.name);p=p.parent;}
  out.push(`${s.name} ${s.id} page=${p?p.id+' '+p.name:'?'} parent=${s.parent.type}:${s.parent.name} x=${Math.round(s.x)} y=${Math.round(s.y)}`);
}
const other=figma.root.children.map(p=>p.name+'='+p.id+':'+p.children.length);
out.push('counts: '+other.join(' | '));
return out.join('\n');

